def transform(grid):
    from collections import Counter
    H, W = len(grid), len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    specials = sorted([c for c in cnt if c != bg], key=lambda c: cnt[c])
    out = [row[:] for row in grid]
    if len(specials) < 2:
        return out
    M, B = specials[0], specials[1]
    mcells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == M]
    if not mcells:
        return out
    bars = []
    for c in range(W):
        r = 0
        while r < H:
            if grid[r][c] == B:
                r0 = r
                while r < H and grid[r][c] == B:
                    r += 1
                if r - r0 >= 2:
                    bars.append(('V', c, r0, r - 1))
            else:
                r += 1
    for r in range(H):
        c = 0
        while c < W:
            if grid[r][c] == B:
                c0 = c
                while c < W and grid[r][c] == B:
                    c += 1
                if c - c0 >= 2:
                    bars.append(('H', r, c0, c - 1))
            else:
                c += 1
    if not bars:
        for r, c in mcells:
            out[r][c] = 4
        return out
    if bars[0][0] == 'V':
        mpos = set(r for r, c in mcells)
    else:
        mpos = set(c for r, c in mcells)
    def cover(b):
        return sum(1 for p in mpos if b[2] <= p <= b[3])
    bars = sorted(bars, key=lambda b: -cover(b))
    P = bars[0]
    N = bars[1] if len(bars) > 1 else None
    oP, fP, aP, bP = P
    for (r, c) in mcells:
        if oP == 'V':
            lo, hi = min(c, fP), max(c, fP)
            for x in range(lo + 1, hi):
                if grid[r][x] == bg:
                    out[r][x] = M
        else:
            lo, hi = min(r, fP), max(r, fP)
            for y in range(lo + 1, hi):
                if grid[y][c] == bg:
                    out[y][c] = M
    if N is not None:
        oN, fN, aN, bN = N
        offs = [p - aP for p in sorted(mpos)]
        lo, hi = min(offs), max(offs)
        for j in range(lo, hi + 1):
            if not any(p == aP + j for p in mpos):
                continue
            if oP == 'V':
                r = aN + j
                if 0 <= r < H:
                    for c in range(W):
                        if c != fN and grid[r][c] == bg:
                            out[r][c] = M
            else:
                c = aN + j
                if 0 <= c < W:
                    for r in range(H):
                        if r != fN and grid[r][c] == bg:
                            if not (0 in offs and r == fP):
                                out[r][c] = M
    for r, c in mcells:
        out[r][c] = 4
    return out
